async function refreshEtsyConnections(){
  try{
    const response=await fetch('/api/etsy/status?fresh='+Date.now()),result=await response.json();
    if(!result.ok)throw new Error(result.error||'Etsy status failed');
    const connected=(result.shops||[]).filter(item=>item.connected).length;
    $$('.real-store-list [data-etsy-shop]').forEach(button=>{
      const item=(result.shops||[]).find(entry=>entry.shop===button.dataset.etsyShop),status=button.closest('article')?.querySelector('em');
      button.dataset.connected=String(Boolean(item?.connected));
      button.textContent=item?.connected?'פרטי החיבור':'חיבור החנות';
      if(status){status.textContent=item?.connected?'מחוברת · LIVE':result.configured?'מוכנה לחיבור':'נדרשת השלמת סוד';status.className=item?.connected?'status success':'status warn'}
    });
    const readiness=$('.etsy-connect-board .connection-readiness');
    if(readiness){readiness.querySelector('b').textContent=`${connected} מתוך 3 חנויות מחוברות`;readiness.querySelector('small').textContent=result.configured?'האפליקציה אושרה · אפשר לחבר כל חנות בפרוקסי שלה':'האפליקציה אושרה · נדרשת השלמת Shared Secret חד־פעמית'}
    const source=[...$$('.integration-list button')].find(node=>node.querySelector('b')?.textContent==='Etsy');
    if(source){source.querySelector('small').textContent=`${connected} מתוך 3 חנויות מחוברות`;const badge=source.querySelector('em');badge.textContent=connected===3?'מחובר':connected?'בתהליך':'מוכן';badge.className=connected===3?'status success':'status warn'}
    const params=new URLSearchParams(location.search);
    if(params.get('etsy')==='connected'){toast(`${params.get('shop')||'חנות Etsy'} חוברה בהצלחה`);history.replaceState({},'',location.pathname)}
  }catch(error){console.warn('Etsy connection status unavailable')}
}


async function refreshSupplierConnection(){
  try{
    const response=await fetch('/api/supplier/sync'),result=await response.json();
    if(!response.ok||!result.ok)throw new Error(result.error||'Supplier sync failed');
    supplierLive=result.data;
    supplierOrders=(result.data.orders||[]).map(row=>{const resolved=row.priceMatched&&Number.isFinite(Number(row.salePrice)),total=resolved?Number(row.salePrice)*Number(row.quantity||1):0,key=productIdentity(row),saved=loadProductCosts()[key]||{},product=Number.isFinite(Number(saved.product))?Number(saved.product):Number(row.supplierCost||0),shipping=Number.isFinite(Number(saved.shipping))?Number(saved.shipping):0,baseFees=resolved?feeFor('Etsy',total):0,fees=baseFees+(Number(saved.fees)||0),hasShipping=Number.isFinite(Number(saved.shipping));return{id:row.orderNumber||('ETSY-'+row.listingId),client:row.store,customer:row.customerName||'לקוח Etsy',item:row.variant?row.title+' · '+row.variant:row.title,platform:'Etsy',channel:'לא מחובר',total,refund:0,shipping,product,fees,baseFees,costComplete:resolved&&hasShipping,status:row.shippingStatus,createdAt:row.date,source:'supplier-live',productKey:key,listingId:row.listingId,sku:row.sku,quantity:Number(row.quantity||1),priceSource:resolved?'מחיר Etsy ציבורי':'מחיר מכירה חסר',trackingNumber:row.trackingNumber,courier:row.courier}});
    orders=[...shopifyOrders,...supplierOrders];
    Object.assign(stores.cursed,{status:'גיליון ספק · LIVE'});Object.assign(stores.select,{status:'גיליון ספק · LIVE'});Object.assign(stores.nerd,{status:'גיליון ספק · LIVE'});
    if(document.body.classList.contains('authenticated'))renderAll();
  }catch(error){console.warn('Supplier connection unavailable')}
}
async function refreshShopifyConnection(force=false){
  const sourceStatus=document.querySelector('#shopify-source-status');
  const kicker=document.querySelector('#shopify-board-kicker');
  const board=document.querySelector('.shopify-connect-board');
  if(!sourceStatus||!board)return;
  try{
    const refreshButton=$('#refresh-data');
    if(refreshButton&&force){refreshButton.disabled=true;refreshButton.textContent='מרענן…'}
    const response=await fetch('/api/shopify/sync'+(force?'?force=1':''),{method:'POST',headers:{'content-type':'application/json'}});
    const result=await response.json();
    if(!result.ok||!result.data?.connected)throw new Error(result.error||'Connection failed');
    const data=result.data;
    liveShopify=data;
    liveLoading=false;
    if(data.ordersAccess&&Array.isArray(data.orders)){
      const statusLabel=order=>order.cancelledAt?'בוטלה':order.displayFulfillmentStatus==='FULFILLED'?'נמסר':order.displayFulfillmentStatus==='PARTIALLY_FULFILLED'?'נשלח חלקית':order.displayFinancialStatus==='REFUNDED'?'הוחזר':order.displayFinancialStatus==='PAID'?'בטיפול':'ממתין';
      const savedCosts=loadLiveCosts();shopifyOrders=data.orders.map(order=>{const saved=savedCosts[order.name]||{},hasProduct=Number.isFinite(Number(saved.product))&&saved.product!=='',hasShipping=Number.isFinite(Number(saved.shipping))&&saved.shipping!=='';return{id:order.name,client:'Z‑Royal',customer:'Shopify',item:'הזמנה מ־Shopify',platform:'Shopify',channel:'לא מחובר',total:Number(order.totalPriceSet?.shopMoney?.amount||0),refund:Number(order.totalRefundedSet?.shopMoney?.amount||0),shipping:hasShipping?Number(saved.shipping):0,product:hasProduct?Number(saved.product):0,fees:Number(saved.fees||0),costComplete:hasProduct&&hasShipping,status:statusLabel(order),createdAt:order.createdAt,source:'shopify-live'}});orders=[...shopifyOrders,...supplierOrders];
    }
    sourceStatus.textContent=data.ordersAccess?'מחוברת':'מחוברת · נדרש אישור הזמנות';
    sourceStatus.className=data.ordersAccess?'status success':'status warn';
    kicker.textContent=data.ordersAccess?'SHOPIFY מחוברת ומסונכרנת':'SHOPIFY מחוברת';
    const copy=board.querySelector('.shopify-connect-copy');
    const action=board.querySelector('.shopify-connect-action');
    copy.querySelector('h2').textContent=data.ordersAccess?`${data.shop.name} מחוברת בזמן אמת`:`${data.shop.name} מחוברת — חסר אישור להזמנות`;
    copy.querySelector('p').innerHTML=data.ordersAccess?`החיבור ל־<b>by-z-royal.myshopify.com</b> פעיל. נתוני Shopify זמינים לסנכרון אוטומטי.`:`החנות אומתה בהצלחה. כדי לקרוא מכירות ורווחיות צריך לאשר פעם אחת את הרשאת <b>Orders</b> ב־Shopify.`;
    action.querySelector('em').textContent=data.ordersAccess?'מחובר':'נדרש אישור אחד';
    action.querySelector('button').textContent=data.ordersAccess?'סנכרון פעיל ✓':'פתיחת Shopify לאישור';
    action.querySelector('button').onclick=()=>window.open('https://dev.shopify.com/dashboard','_blank','noopener');
    const sync=$('.sync-state');
    if(sync){const updated=data.syncedAt?new Intl.DateTimeFormat('he-IL',{hour:'2-digit',minute:'2-digit'}).format(new Date(data.syncedAt)):'';sync.innerHTML=`<span class="live-dot"></span><div><b>Z‑Royal מחוברת · LIVE</b><small>${data.summary?.orderCount||0} הזמנות · עודכן ${updated}${data.refreshing?' · עדכון חדש רץ ברקע':''}</small></div>`}
    if(refreshButton){refreshButton.disabled=false;refreshButton.textContent='רענון עכשיו'}
    renderAll();
  }catch(error){
    liveLoading=false;
    sourceStatus.textContent='דורש בדיקה';
    sourceStatus.className='status warn';
    const refreshButton=$('#refresh-data');if(refreshButton){refreshButton.disabled=false;refreshButton.textContent='רענון עכשיו'}
  }
}
